import { ok, fail } from './result.js';

export const RATES = {
  EUR: 1,
  USD: 1.085,
  GBP: 0.8425,
};

export function convert(cents, currency) {
  if (!RATES[currency]) {
    return fail('UNKNOWN_CURRENCY');
  }

  const convertedCents = Math.round(cents * RATES[currency]);
  return ok(convertedCents);
}

export function formatMoney(cents, currency) {
  if (!RATES[currency]) {
    return fail('UNKNOWN_CURRENCY');
  }

  const amount = cents / 100;
  const formatted = amount.toFixed(2);

  switch (currency) {
    case 'USD':
      return ok(`$${formatted}`);
    case 'GBP':
      return ok(`£${formatted}`);
    case 'EUR':
      return ok(`€${formatted}`);
    default:
      return fail('UNKNOWN_CURRENCY');
  }
}

