import { ok, fail } from './result.js';

export const RATES = {
  EUR: 1,
  USD: 1.085,
  GBP: 0.8425,
};

export function convert(cents, currency) {
  if (!RATES[currency]) {
    return fail('UNKNOWN_CURRENCY');
  }

  const convertedCents = Math.round(cents * RATES[currency]);
  return ok(convertedCents);
}

export function formatMoney(cents, currency) {
  if (!RATES[currency]) {
    return fail('UNKNOWN_CURRENCY');
  }

  const amount = cents / 100;
  const formatted = amount.toFixed(2);

  switch (currency) {
    case 'USD':
      return ok('$' + formatted);
    case 'GBP':
      return ok('£' + formatted);
    case 'EUR':
      return ok('€' + formatted);
    default:
      return fail('UNKNOWN_CURRENCY');
  }
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CREDIT_TOO_HIGH: 'Credit amount cannot exceed invoice total.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a real date in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount must be a number between 0 and 100.',
  LINE_NOT_FOUND: 'That SKU is not on this invoice.',
  NO_LINES: 'Invoice must have at least one line.',
  NOT_DRAFT: 'Cannot modify an invoice that is not in draft status.',
  NOT_ISSUED: 'Cannot record a payment on an invoice that is not issued.',
  OVERPAYMENT: 'Payment is more than the amount still owed.',
  QTY_INVALID: 'Line quantity must be a positive integer.',
  TERMS_INVALID: 'Terms must be NET14, NET30, or EOM.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  VOUCHER_EXISTS: 'An invoice can only have one voucher.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

