node -e "
import { writeFileSync } from 'fs';

const content = \`import test from 'node:test';
import assert from 'node:assert/strict';
import { convert, formatMoney, RATES } from '../src/money.js';

test('RATES includes EUR, USD, GBP', () => {
  assert.ok(RATES.EUR);
  assert.ok(RATES.USD);
  assert.ok(RATES.GBP);
});

test('RATES values are correct', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD applies rate', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, Math.round(10000 * 1.085));
});

test('convert EUR to GBP applies rate', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, Math.round(10000 * 0.8425));
});

test('convert with unknown currency returns error', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert rounds to nearest cent', () => {
  const result = convert(1, 'USD');
  // 1 * 1.085 = 1.085, rounds to 1
  assert.equal(result.value, 1);
});

test('convert with fractional result rounds correctly', () => {
  const result = convert(100, 'USD');
  // 100 * 1.085 = 108.5, rounds to 109 or 108?
  assert.equal(Number.isInteger(result.value), true);
});

test('convert handles zero amount', () => {
  const result = convert(0, 'EUR');
  assert.equal(result.value, 0);
});

test('convert handles large amounts', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, Math.round(1000000 * 1.085));
});

test('formatMoney returns ok with formatted string', () => {
  const result = formatMoney(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'string');
});

test('formatMoney USD includes dollar sign', () => {
  const result = formatMoney(10000, 'USD');
  assert.ok(result.value.includes('\$'));
});

test('formatMoney GBP includes pound sign', () => {
  const result = formatMoney(10000, 'GBP');
  assert.ok(result.value.includes('£'));
});

test('formatMoney EUR includes euro sign', () => {
  const result = formatMoney(10000, 'EUR');
  assert.ok(result.value.includes('€'));
});

test('formatMoney formats with 2 decimals', () => {
  const result = formatMoney(10000, 'USD');
  assert.ok(result.value.includes('.'));
  const parts = result.value.split('.');
  assert.equal(parts[1].length, 2);
});

test('formatMoney USD formats 10000 cents as \$100.00', () => {
  const result = formatMoney(10000, 'USD');
  assert.equal(result.value, '\$100.00');
});

test('formatMoney GBP formats 10000 cents as £100.00', () => {
  const result = formatMoney(10000, 'GBP');
  assert.equal(result.value, '£100.00');
});

test('formatMoney EUR formats 10000 cents as €100.00', () => {
  const result = formatMoney(10000, 'EUR');
  assert.equal(result.value, '€100.00');
});

test('formatMoney with unknown currency returns error', () => {
  const result = formatMoney(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('formatMoney handles zero amount', () => {
  const result = formatMoney(0, 'EUR');
  assert.equal(result.value, '€0.00');
});

test('formatMoney handles single cent', () => {
  const result = formatMoney(1, 'USD');
  assert.equal(result.value, '\$0.01');
});

test('formatMoney handles amounts without cents', () => {
  const result = formatMoney(50000, 'GBP');
  assert.equal(result.value, '£500.00');
});

test('formatMoney handles odd amounts', () => {
  const result = formatMoney(12345, 'EUR');
  assert.equal(result.value, '€123.45');
});

test('convert and formatMoney together', () => {
  const converted = convert(10000, 'USD');
  if (converted.ok) {
    const formatted = formatMoney(converted.value, 'USD');
    assert.equal(formatted.ok, true);
    assert.ok(formatted.value.startsWith('\$'));
  }
});

test('conversion precision preserved', () => {
  // 1 EUR = 1.085 USD
  // 1 cent EUR = 0.01085 USD = 0.01085 cents USD
  // Should round appropriately
  const result = convert(1, 'USD');
  assert.equal(Number.isInteger(result.value), true);
});

test('GBP conversion less than EUR', () => {
  const eurResult = convert(10000, 'EUR');
  const gbpResult = convert(10000, 'GBP');
  assert(gbpResult.value < eurResult.value);
});

test('USD conversion more than EUR', () => {
  const eurResult = convert(10000, 'EUR');
  const usdResult = convert(10000, 'USD');
  assert(usdResult.value > eurResult.value);
});
\`;

writeFileSync('./test/money.test.js', content);
console.log('Test file created');
"

