  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /\nKite & Co\n/);
});

test('renderInvoiceText uses customerId as fallback for unknown customer', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const text = renderInvoiceText(invoice);
  assert.match(text, /\nC-999\n/);
});

test('renderInvoiceText formats zero price correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'TEST', qty: 1, name: 'Test product', unitPrice: 0, vatRate: 0 }],
  };

  const text = renderInvoiceText(invoice);
  assert.match(text, /€0\.00/);
});

test('renderInvoiceText calculates correct total with discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const text = renderInvoiceText(invoice);
  // 5 * €85.00 = €425.00, with 10% discount = €42.50, after discount €382.50
  // VAT 21% on €382.50 = €80.325, rounds to €80.32 (banker's rounding)
  // Total: €425.00 - €42.50 + €80.32 = €462.82
  assert.match(text, /Total: €462\.82$/);
});

test('renderInvoiceText shows discounted line total correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, name: 'Design work (hour)', unitPrice: 1000, vatRate: 21, discountPercent: 20 },
    ],
  };

  const text = renderInvoiceText(invoice);
  // 10 * €10.00 = €100.00 (line total before discount)
  assert.match(text, /10 Design work \(hour\) €10\.00 €100\.00/);
});

test('renderInvoiceText handles multiple lines with different discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'SKU1', qty: 10, name: 'Product A', unitPrice: 1000, vatRate: 21, discountPercent: 10 },
      { sku: 'SKU2', qty: 5, name: 'Product B', unitPrice: 2000, vatRate: 21, discountPercent: 20 },
    ],
  };

  const text = renderInvoiceText(invoice);
  // Line 1: 10 * €10.00 = €100.00, 10% discount = €10.00, after discount €90.00, VAT 21% = €18.90
  // Line 2: 5 * €20.00 = €100.00, 20% discount = €20.00, after discount €80.00, VAT 21% = €16.80
  // Total VAT: €18.90 + €16.80 = €35.70
  // Total: €200.00 - €30.00 + €35.70 = €205.70
  assert.match(text, /Total: €205\.70$/);
});

