test('invoiceTotals returns subtotal, discount, vat, and total', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 5 * 8500 = 42500
  // discount: 42500 * 10% = 4250
  // after discount: 42500 - 4250 = 38250
  // vat: 38250 * 21% = 8032.5, rounds to 8032 (banker's rounding)
  // total: 42500 - 4250 + 8032 = 46282
  assert.deepEqual(totals, { subtotal: 42500, discount: 4250, vat: 8032, voucher: 0, total: 46282 });
});

test('invoiceTotals with no discounts or VAT', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 0, vat: 0, voucher: 0, total: 42500 });
});

